import dns.resolver
import requests

# 定义目标域
target_domain = "example.com"

# 子域名字典列表，可以根据实际需求扩展
subdomain_list = ["www", "admin", "test", "ftp"]

def enum_subdomains(domain, subdomains):
    found_domains = []
    for sub in subdomains:
        subdomain = f"{sub}.{domain}"
        try:
            answers = dns.resolver.resolve(subdomain, 'A')
            for rdata in answers:
                print(f"Found: {subdomain} with IP: {rdata.address}")
                found_domains.append(subdomain)
        except (dns.resolver.NXDOMAIN, dns.resolver.NoAnswer):
            pass
    return found_domains

def check_http_service(domains):
    for domain in domains:
        try:
            response = requests.get(f"http://{domain}", timeout=5)
            if response.status_code == 200:
                print(f"HTTP service is alive at: http://{domain}")
            else:
                print(f"No HTTP service or service not responding at: {domain}")
        except (requests.RequestException, ConnectionError):
            pass

if __name__ == "__main__":
    found_subdomains = enum_subdomains(target_domain, subdomain_list)
    check_http_service(found_subdomains)
```

