import requests

def fetch_schema_from_graphql(endpoint):
    # 定义内省查询语句
    introspection_query = """
    query IntrospectionQuery {
      __schema {
        types {
          kind
          name
          description
          fields(includeDeprecated: true) {
            name
            args {
              ...InputValue
            }
            type {
              kind
              name
              ofType {
                kind
                name
                ofType {
                  kind
                  name
                  ofType {
                    kind
                    name
                  }
                }
              }
            }
            isDeprecated
            deprecationReason
          },
          inputFields {
            ...InputValue
          },
          interfaces {
            ...TypeRef
          },
          enumValues(includeDeprecated: true) {
            name
            description
            isDeprecated
            deprecationReason
          },
          possibleTypes {
            ...TypeRef
          }
        }
      }
    }

    fragment InputValue on __InputValue {
      name
      description
      type { ...TypeRef }
      defaultValue
    }

    fragment TypeRef on __Type {
      kind
      name
      ofType {
        kind
        name
        ofType {
          kind
          name
          ofType {
            kind
            name
          }
        }
      }
    }
    """

    # 发送请求到GraphQL端点
    headers = {'Content-Type': 'application/json'}
    payload = {'query': introspection_query}
    response = requests.post(endpoint, json=payload, headers=headers)

    # 检查响应状态码
    if response.status_code == 200:
        return response.json()
    else:
        raise Exception(f"Failed to fetch schema. Status code: {response.status_code}, Response: {response.text}")

# 使用示例
if __name__ == "__main__":
    graphql_endpoint = "https://your-graphql-endpoint.com/graphql"
    try:
        schema_data = fetch_schema_from_graphql(graphql_endpoint)
        print("GraphQL Schema fetched successfully.")
        # 这里可以对schema_data进行进一步的分析或处理
    except Exception as e:
        print(f"Error: {e}")
```

