                    return var_export($param, true);
                }, $step['params']));
            } else {
                $output .= var_export($step['params'], true);
            }
            $output .= ");\n";
        }
        return $output;
    }

    public function execute() {
        foreach ($this->popChain as $step) {
            $obj = new $step['class']();
            call_user_func_array([$obj, $step['method']], is_array($step['params']) ? $step['params'] : [$step['params']]);
        }
    }
}

