```cpp
#include <windows.h>
#include <tlhelp32.h>

// 从内存中加载DLL的函数指针类型定义
typedef BOOL(WINAPI *DllMainProc)(HINSTANCE, DWORD, LPVOID);

// 创建一个新的进程并加载DLL到这个进程中
BOOL LoadDllInProcess(LPVOID lpImageBase, SIZE_T imageSize) {
    // 获取系统中第一个运行中的进程（通常是System进程）
    PROCESSENTRY32 pe32;
    HANDLE hSnapshot = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    if (hSnapshot == INVALID_HANDLE_VALUE) return FALSE;

    pe32.dwSize = sizeof(PROCESSENTRY32);
    if (!Process32First(hSnapshot, &pe32)) {
        CloseHandle(hSnapshot);
        return FALSE;
    }

    // 找到一个目标进程，这里我们选择第一个运行中的进程
    HANDLE hTargetProc = OpenProcess(PROCESS_ALL_ACCESS, FALSE, pe32.th32ProcessID);
    if (!hTargetProc) {
        CloseHandle(hSnapshot);
        return FALSE;
    }

    // 在目标进程中分配内存来保存DLL数据
    LPVOID lpRemoteMemory = VirtualAllocEx(hTargetProc, NULL, imageSize, MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE);
    if (!lpRemoteMemory) {
        CloseHandle(hTargetProc);
        CloseHandle(hSnapshot);
        return FALSE;
    }

    // 将DLL数据从本地内存复制到目标进程的内存
    if (!WriteProcessMemory(hTargetProc, lpRemoteMemory, lpImageBase, imageSize, NULL)) {
        VirtualFreeEx(hTargetProc, lpRemoteMemory, 0, MEM_RELEASE);
        CloseHandle(hTargetProc);
        CloseHandle(hSnapshot);
        return FALSE;
    }

    // 在目标进程中创建一个线程来执行DLL的入口点
    HANDLE hThread = CreateRemoteThread(hTargetProc, NULL, 0, (LPTHREAD_START_ROUTINE)lpRemoteMemory, NULL, 0, NULL);
    if (!hThread) {
        VirtualFreeEx(hTargetProc, lpRemoteMemory, 0, MEM_RELEASE);
        CloseHandle(hTargetProc);
        CloseHandle(hSnapshot);
        return FALSE;
    }

    WaitForSingleObject(hThread, INFINITE);
    CloseHandle(hThread);

    VirtualFreeEx(hTargetProc, lpRemoteMemory, 0, MEM_RELEASE);
    CloseHandle(hTargetProc);
    CloseHandle(hSnapshot);

    return TRUE;
}
```

